<?php $title = __('Payments'); ?>
<form method="get" class="toolbar"><input type="hidden" name="r" value="cashbank/payments"><input type="date" name="from" value="<?= e($from) ?>"><input type="date" name="to" value="<?= e($to) ?>"><button class="btn btn-primary" type="submit"><?= __('Filter') ?></button><span style="flex:1"></span><a class="btn btn-primary" href="<?= e(url('cashbank/payments/new')) ?>"><?= __('+ New Payment') ?></a></form>
<div class="panel"><div class="table-wrap"><table class="tbl"><thead><tr><th><?= __('Payment') ?></th><th><?= __('Date') ?></th><th><?= __('Party') ?></th><th><?= __('From') ?></th><th class="num"><?= __('Amount') ?></th><th><?= __('Reference') ?></th><th></th></tr></thead>
<tbody><?php foreach ($p['rows'] as $r): ?><tr><td class="mono"><?= e($r['payment_no']) ?></td><td><?= date_display($r['date']) ?></td><td><?= e($r['party'] ?? '—') ?></td><td><?= e($r['account']) ?></td><td class="num"><?= money($r['amount']) ?></td><td><?= e($r['reference'] ?? '—') ?></td><td><a class="btn btn-outline btn-sm" href="<?= e(url('cashbank/payments/' . (int)$r['id'])) ?>"><?= __('View/Print') ?></a></td></tr>
<?php endforeach; ?><?php if (!$p['rows']): ?><tr><td colspan="6" class="muted"><?= __('No payments in range.') ?></td></tr><?php endif; ?></tbody></table></div>
